// DeleteFunctionsCustomDomain removes a custom domain registered on the branch and stops routing it. **Note**: This endpoint is currently in Beta.
//
// Parameters:
//
//	projectId: The Neon project ID
//	branchId: The Neon branch ID
//	domain: The registered custom domain (case-insensitive).
func DeleteFunctionsCustomDomain(ctx context.Context, clientConfig ClientConfig, params DeleteFunctionsCustomDomainParams, opts ...RequestOption) (any, error) {
	projectId := params.ProjectId
	branchId := params.BranchId
	domain := params.Domain

	if err := ValidatePattern("project_id", projectId, "^[a-z0-9-]{1,60}$"); err != nil {
		return nil, err
	}

	if err := ValidatePattern("branch_id", branchId, "^[a-z0-9-]{1,60}$"); err != nil {
		return nil, err
	}

	if err := ValidateLength("domain", domain, LengthOpts{Min: Ptr[int](3), Max: Ptr[int](254)}); err != nil {
		return nil, err
	}
	if err := ValidatePattern("domain", domain, "^[A-Za-z0-9.-]+$"); err != nil {
		return nil, err
	}

	_, err := DoEmptyCfg(ctx, &clientConfig, "DELETE", fmt.Sprintf("/projects/%s/branches/%s/custom-domains/%s", EncodePathSegment(projectId), EncodePathSegment(branchId), EncodePathSegment(domain)), &RequestOpts{
		OperationID: "DeleteFunctionsCustomDomain",
		Errors:      ErrorDecoders{"default": decodeErrorData[GeneralError]},
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return nil, nil
}
